Object.assign(window.TEM8_DICTIONARY, {"voluntary":{"media":{"uk":"media/uk/voluntary__gb_1.mp3","us":"media/us/voluntary__us_1.mp3"},"oxford":{"phon":"ˈvɒləntri","pos":"adjective","senses":[{"en":"done willingly, not because you are forced","cn":"自愿的；志愿的；主动的；自告奋勇的","lab":"British English","ex":{"en":"a voluntary agreement","cn":"自愿协议"}},{"en":"done by people who choose to do it without being paid","cn":"自愿性的；无偿的；义务性的","g":"[usually before noun]","ex":{"en":"I do some voluntary work at the local hospital.","cn":"我在当地医院从事一些义务性工作。"}},{"en":"doing a job without wanting to be paid for it","cn":"自愿的；志愿的；义务的；自发的","g":"[only before noun]","ex":{"en":"The homeless hostel is staffed by voluntary workers.","cn":"无家可归者宿舍由志愿者组成。"}},{"en":"that you can control","cn":"随意的；可以控制的","lab":"specialist"},{"en":"a piece of music played before, during or after a church service, usually on an organ","cn":"仪式终始曲，即兴曲（通常用风琴在教堂礼拜仪式前后或期间演奏）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自愿的;志愿的;主动的;自发的","en":"Voluntary actions or activities are done because someone chooses to do them and not because they have been forced to do them.","ex":{"en":"Attention is drawn to a special voluntary course in Commercial French","cn":"一门特别的商务法语选修课引起了大家的关注。"}},{"pos":"ADJ 形容词","cn":"（工作）无偿的，义务性的","en":"Voluntary work is done by people who are not paid for it, but who do it because they want to do it.","ex":{"en":"In her spare time she does voluntary work","cn":"她在业余时间做义工。"}},{"pos":"ADJ 形容词","cn":"（工作者）志愿的,无偿服务的","en":"A voluntary worker is someone who does work without being paid for it, because they want to do it.","ex":{"en":"Apna Arts has achieved more with voluntary workers in three years than most organisations with paid workers have achieved in ten","cn":"“我们”艺术中心依靠志愿者在3年内取得的成就超过了大多数雇用受薪员工的机构10年中取得的成绩。"}},{"pos":"ADJ 形容词","cn":"（机构或组织）志愿的，义务性的","en":"A voluntary organization is controlled and organized by the people who have chosen to work for it, often without being paid, rather than receiving help or money from the government.","ex":{"en":"Some local authorities and voluntary organizations also run workshops for disabled people","cn":"一些当地机构和志愿组织也为残疾人开设了一些工场。"}}]},"examples":[{"en":"I do some voluntary work at the local hospital.","cn":"我在当地医院从事一些义务性工作。"},{"en":"voluntary services/bodies/agencies/organizations (= organized, controlled or supported by people who choose to do this and are usually not paid)","cn":"义务性服务/团体/机构/组织"}]},"voyage":{"media":{"uk":"media/uk/voyage__gb_1.mp3","us":"media/us/voyage__us_1.mp3"},"oxford":{"phon":"ˈvɔɪɪdʒ","pos":"noun","senses":[{"en":"a long journey, especially by sea or in space","cn":"航行；（尤指）航海，航天","lab":"figurative","ex":{"en":"an around-the-world voyage","cn":"环球航行"}},{"en":"to travel, especially by sea or in space over a long distance","cn":"（尤指海上或太空）航行，远航","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行;航行;航海;航天","en":"A voyage is a long journey on a ship or in a spacecraft. →see usage note at:","ex":{"en":"He aims to follow Columbus's voyage to the West Indies.","cn":"他打算重走哥伦布到达西印度群岛的航行路线。"}},{"pos":"VERB 动词","cn":"旅行;（尤指）航海旅行","en":"To voyage to a place means to travel there, especially by sea.","ex":{"en":"The Greenpeace flagship is voyaging through the Arctic cold of the Barents Sea.","cn":"绿色和平组织的旗舰正在穿越巴伦支海的北极寒冷地带。"}}]},"examples":[{"en":"( figurative ) Going to college can be a voyage of self-discovery.","cn":"上大学可以算作自我发现之行。"},{"en":"The Titanic sank on its maiden voyage (= first journey).","cn":"泰坦尼克号首航便沉没了。"}]},"votes":{"lemma":"vote"},"voted":{"lemma":"vote"},"voice":{"media":{"uk":"media/uk/voice__gb_1.mp3","us":"media/us/voice__us_1.mp3"},"oxford":{"phon":"vɔɪs","pos":"noun","senses":[{"en":"the sound or sounds produced through the mouth by a person speaking or singing","cn":"嗓音；说话声；歌唱声","g":"[countable, uncountable]","sc":"sound from mouth","ex":{"en":"I could hear voices in the next room.","cn":"我能听到隔壁说话的声音。"}},{"en":"having a voice of the type mentioned","cn":"有…嗓音的；嗓音…的","sc":"-voiced","ex":{"en":"low-voiced","cn":"嗓门低的"}},{"en":"the right to express your opinion and influence decisions","cn":"发言权；发表意见的权利；影响","g":"[singular]","sc":"opinion","ex":{"en":"Employees should have a voice in the decision-making process.","cn":"雇员在决策的过程中应该有发言权。"}},{"en":"a particular attitude, opinion or feeling that is expressed; a feeling or an opinion that you become aware of inside yourself","cn":"呼声；意见；态度；心声","g":"[countable]","sc":"opinion","ex":{"en":"He pledged that his party would listen to the voice of the people.","cn":"他保证他的政党愿意倾听人民的呼声。"}},{"en":"an organization that expresses the opinion of a particular section of society","cn":"（表达特定群体意见的）喉舌","sc":"opinion","ex":{"en":"The Royal Society is the voice of the British science establishment.","cn":"皇家学会是英国科学界的喉舌。"}},{"en":"the form of a verb that shows whether the subject of a sentence performs the action (the active voice) or is affected by it (the passive voice)","cn":"语态","g":"[singular]","sc":"grammar","ex":{"en":"Can you turn this sentence into the passive voice?","cn":"你能把这句话变成被动语态吗？"}},{"en":"sound produced by movement of the vocal cords used in the pronunciation of vowels and some consonants","cn":"浊音（声带振动发出的元音和某些辅音）","g":"[uncountable]","sc":"phonetics"},{"en":"to tell people your feelings or opinions about something","cn":"表示，表达，吐露（感情或意见）","sc":"give opinion","ex":{"en":"to voice complaints/criticisms/doubts/objections, etc.","cn":"表示不满、批评、怀疑、异议等"},"pos":"verb"},{"en":"to produce a sound with a movement of your vocal cords as well as your breath","cn":"发浊音；发嗓音","sc":"phonetics","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"嗓音;歌声;说话声","en":"When someone speaks or sings, you hear their voice .","ex":{"en":"Miriam's voice was strangely calm","cn":"米里亚姆的声音异乎寻常地平静。"}},{"pos":"N-COUNT 可数名词","cn":"观点;意见","en":"Someone's voice is their opinion on a particular topic and what they say about it.","ex":{"en":"What does one do when a government simply refuses to listen to the voice of the opposition?","cn":"当政府就是不肯听取反对意见时，你该怎么做呢？"}},{"pos":"N-SING 单数名词","cn":"表达意见的权利;发言权","en":"If you have a voice in something, you have the right to express an opinion on it.","ex":{"en":"Egypt is once again accepted as an important voice in Arab politics","cn":"埃及再一次被认为是阿拉伯政治中的一个重要声音。"}},{"pos":"VERB 动词","cn":"表达，吐露（观点或感情）","en":"If you voice something such as an opinion or an emotion, you say what you think or feel.","ex":{"en":"Some scientists have voiced concern that the disease could be passed on to humans","cn":"有些科学家表示了担忧，认为这种病可能传染给人类。"}},{"pos":"N-SING 单数名词","cn":"主动语态/被动语态","en":"In grammar, if a verb is in the active voice, the person who performs the action is the subject of the verb. If a verb is in the passive voice, the thing or person affected by the action is the subject of the verb."},{"pos":"PHRASE 短语","cn":"(克服恐惧、惊讶或困难）开口说话","en":"If someone finds their voice, they start to speak in spite of fear or surprise or difficult circumstances.","ex":{"en":"'Kurt Kohn was my paternal grandfather's name,' Laura said when she found her voice.","cn":"“库尔特·科恩是我祖父的名字，”克服了恐惧的劳拉开口说道。"}},{"pos":"PHRASE 短语","cn":"（作家）形成个人风格，找到属于自己的写作主题","en":"If you say that a writer finds his or her voice, you mean that he or she finds a style and subject matter that are personal and original.","ex":{"en":"The poems which he wrote in the trenches are generally agreed to be those in which he found his true voice.","cn":"他在战壕里创作的那些诗歌被公认为是他找到了自己声音的作品。"}},{"pos":"PHRASE 短语","cn":"表达（观点）；表露（需求）；表白（心迹）","en":"If you give voice to an opinion, a need, or a desire, you express it aloud.","ex":{"en":"...a community radio run by the Catholic Church which gave voice to the protests of the slum-dwellers.","cn":"一家由天主教教会开办的、贫民区居民可以在其节目中表达抗议的社区电台"}},{"pos":"PHRASE 短语","cn":"放低声音;轻声讲话","en":"If someone tells you to keep your voice down, they are asking you to speak more quietly.","ex":{"en":"Keep your voice down, for goodness sake.","cn":"看在上天的份儿上，小点儿声。"}},{"pos":"PHRASE 短语","cn":"（因病）失声,不能讲话","en":"If you lose your voice, you cannot speak for a while because of an illness.","ex":{"en":"I had to be careful not to get a sore throat and lose my voice.","cn":"我必须得小心，免得嗓子痛，话都说不出来。"}},{"pos":"PHRASE 短语","cn":"提高嗓门/压低嗓门","en":"If you raise your voice, you speak more loudly. If you lower your voice, you speak more quietly.","ex":{"en":"He raised his voice for the benefit of the other two women","cn":"为了让其他两个女人听清，他提高了嗓门。"}},{"pos":"PHRASE 短语","cn":"以最大的声音;声嘶力竭地","en":"If you say something at the top of your voice, you say it as loudly as possible.","ex":{"en":"'Damn!' he yelled at the top of his voice.","cn":"“该死！”他声嘶力竭地喊道。"}},{"pos":"PHRASE 短语","cn":"异口同声地;众口一词地","en":"If a number of people say something with one voice, they all express the same opinion about something.","ex":{"en":"This would enable the community to speak with one voice in world affairs.","cn":"这将使该共同体在国际事务上能以一个声音讲话。"}}]},"examples":[{"en":"to speak in a deep/soft/loud/quiet, etc. voice","cn":"低沉地说、轻柔地说、大声地说、轻声地说等"},{"en":"A number of parents have voiced concern about their children's safety.","cn":"一些家长对他们子女的安全表示了担心。"}]},"volunteer":{"media":{"uk":"media/uk/volunteer__gb_1.mp3","us":"media/us/volunteer__us_1.mp3"},"oxford":{"phon":"ˌvɒlənˈtɪə(r)","pos":"noun","senses":[{"en":"a person who does a job without being paid for it","cn":"义务工作者；志愿者","ex":{"en":"Schools need volunteers to help children to read.","cn":"学校需要义务工作者帮助儿童阅读。"}},{"en":"a person who offers to do something without being forced to do it","cn":"自告奋勇者；主动做某事的人","ex":{"en":"Are there any volunteers to help clear up?","cn":"有人愿意帮忙打扫吗？"}},{"en":"a person who chooses to join the armed forces without being forced to join","cn":"志愿兵；义勇兵"},{"en":"to offer to do something without being forced to do it or without getting paid for it","cn":"自愿做；义务做；无偿做","g":"[intransitive, transitive]","ex":{"en":"He has been volunteering for 11 years now.","cn":"迄今为止，他已经从事志愿服务11年了。"},"pos":"verb"},{"en":"to suggest something or tell somebody something without being asked","cn":"主动建议（或告诉）","g":"[transitive]","ex":{"en":"to volunteer advice","cn":"主动提出忠告"},"pos":"verb"},{"en":"to join the army, etc. without being forced to","cn":"自愿参军；当志愿兵","g":"[intransitive]","ex":{"en":"He wasn't conscripted. He volunteered.","cn":"他没有被征召入伍。他是自愿的。"},"pos":"verb"},{"en":"to suggest somebody for a job or an activity, even though they may not want to do it","cn":"（未经当事人同意）举荐","g":"[transitive]","ex":{"en":"They volunteered me for the job of interpreter.","cn":"他们擅自指定由我担任口头翻译。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"志愿者;义务工作者;义工","en":"A volunteer is someone who does work without being paid for it, because they want to do it.","ex":{"en":"She now helps in a local school as a volunteer three days a week","cn":"目前她在当地的一家学校做志愿工作，一周去3天。"}},{"pos":"N-COUNT 可数名词","cn":"自告奋勇者;主动做事者","en":"A volunteer is someone who offers to do a particular task or job without being forced to do it.","ex":{"en":"Right. What I want now is two volunteers to come down to the front","cn":"好了，现在我需要两个自告奋勇的人到前面来。"}},{"pos":"VERB 动词","cn":"自告奋勇;主动要求","en":"If you volunteer to do something, you offer to do it without being forced to do it.","ex":{"en":"Aunt Mary volunteered to clean up the kitchen","cn":"玛丽阿姨主动要求清扫厨房。"}},{"pos":"VERB 动词","cn":"主动提供（信息）","en":"If you volunteer information, you tell someone something without being asked.","ex":{"en":"The room was quiet; no one volunteered any further information","cn":"房间很安静，无人主动提供更多的信息。"}},{"pos":"N-COUNT 可数名词","cn":"志愿兵;义勇军","en":"A volunteer is someone who chooses to join the armed forces, especially during a war, as opposed to someone who is forced to join by law.","ex":{"en":"They fought as volunteers with the Afghan guerrillas","cn":"他们作为志愿军和阿富汗的游击队员并肩作战。"}}]},"examples":[{"en":"Schools need volunteers to help children to read.","cn":"学校需要义务工作者帮助儿童阅读。"},{"en":"They volunteered me for the job of interpreter.","cn":"他们擅自指定由我担任口头翻译。"}]},"volume":{"media":{"uk":"media/uk/volume__gb_1.mp3","us":"media/us/volume__us_1.mp3"},"oxford":{"phon":"ˈvɒljuːm","pos":"noun","senses":[{"en":"the amount of space that an object or a substance fills; the amount of space that a container has","cn":"体积；容积；容量","g":"[uncountable, countable]","ex":{"en":"How do you measure the volume of a gas?","cn":"如何测量气体的体积？"}},{"en":"the amount of something","cn":"量；额","g":"[uncountable, countable]","ex":{"en":"the sheer volume (= large amount) of business","cn":"大量业务"}},{"en":"the amount of sound that is produced by a television, radio, etc.","cn":"音量；响度","g":"[uncountable]","ex":{"en":"to turn the volume up/down","cn":"把音量调大／调小"}},{"en":"a book that is part of a series of books","cn":"（成套书中的）一卷，一册","g":"[countable]","ex":{"en":"an encyclopedia in 20 volumes","cn":"一套 20 卷的百科全书"}},{"en":"a book","cn":"书","g":"[countable]","lab":"formal","ex":{"en":"a library of over 50 000 volumes","cn":"藏书 5 万多册的图书馆"}},{"en":"a series of different issues of the same magazine, especially all the issues for one year","cn":"卷，合订本（同一杂志的一系列期刊，尤指一年的）","g":"[countable]","ex":{"en":"‘New Scientist’ volume 142, number 3","cn":"《新科学家》第 142 卷第 3 期"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"量;数额","en":"The volume of something is the amount of it that there is.","ex":{"en":"Senior officials will be discussing how the volume of sales might be reduced.","cn":"高层领导将要讨论销售量如何削减。"}},{"pos":"N-COUNT 可数名词","cn":"体积;容积;容量","en":"The volume of an object is the amount of space that it contains or occupies.","ex":{"en":"It is 2,300 metres above sea level, so a given volume of air contains only about one-third as much oxygen as it would at sea level","cn":"这是在海拔2,300米的高空，因此一定体积空气的含氧量只有海平面处的约1/3。"}},{"pos":"N-COUNT 可数名词","cn":"书;书籍","en":"A volume is a book.","ex":{"en":"...a 125-page volume.","cn":"一本125页的书"}},{"pos":"N-COUNT 可数名词","cn":"（书籍的）卷，册","en":"A volume is one book in a series of books.","ex":{"en":"...the first volume of his autobiography.","cn":"他自传的第一卷"}},{"pos":"N-COUNT 可数名词","cn":"（杂志的）合集，合订本","en":"A volume is a collection of several issues of a magazine, for example all the issues for one year.","ex":{"en":"...bound volumes of the magazine.","cn":"杂志的合订本"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（广播、电视或音响系统的）音量，声量,响度","en":"The volume of a radio, television, or sound system is the loudness of the sound it produces.","ex":{"en":"He turned down the volume","cn":"他调低了音量。"}},{"pos":"PHRASE 短语","cn":"清楚表明;详尽说明;充分说明","en":"If something such as an action speaks volumes about a person or thing, it gives you a lot of information about them.","ex":{"en":"What you wear speaks volumes about you","cn":"你的衣着能传递很多关于你的信息。"}}]},"examples":[{"en":"New roads are being built to cope with the increased volume of traffic.","cn":"正在修建新的道路以应付增加了的交通量。"},{"en":"‘New Scientist’ volume 142, number 3 《","cn":"新科学家》第 142 卷第 3 号"}]},"vomiting":{"lemma":"vomit"},"volcanic":{"media":{"uk":"media/uk/volcanic__gb_1.mp3","us":"media/us/volcanic__us_1.mp3"},"oxford":{"phon":"vɒlˈkænɪk","pos":"adjective","senses":[{"en":"caused or produced by a volcano","cn":"火山的；火山引起的；火山产生的","ex":{"en":"volcanic rocks","cn":"火山岩"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"火山的;由火山引发的","en":"Volcanic means coming from or created by volcanoes.","ex":{"en":"Over 200 people have been killed by volcanic eruptions","cn":"火山喷发已导致200多人丧生。"}}]},"examples":[{"en":"volcanic eruptions","cn":"火山喷发"},{"en":"volcanic rocks","cn":"火山岩"}]},"volcano":{"oxford":{"phon":"vɒlˈkeɪnəʊ","pos":"noun","senses":[{"en":"a mountain with a large opening at the top through which gases and lava (= hot liquid rock) are forced out into the air, or have been in the past","cn":"火山","ex":{"en":"An active volcano may erupt at any time.","cn":"活火山会随时喷发。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火山","en":"A volcano is a mountain from which hot melted rock, gas, steam, and ash from inside the earth sometimes burst.","ex":{"en":"The volcano erupted last year killing about 600 people","cn":"去年那座火山喷发致使约600人遇难。"}}]},"media":{"uk":"media/uk/volcano__gb_1.mp3","us":"media/us/volcano__us_1.mp3"},"examples":[{"en":"An active volcano may erupt at any time.","cn":"活火山会随时喷发。"},{"en":"a dormant volcano (= one that is not active at present)","cn":"休眠火山"}]},"vodka":{"oxford":{"phon":"ˈvɒdkə","pos":"noun","senses":[{"en":"a strong, clear alcoholic drink, made from grain, originally from Russia","cn":"伏特加（一种原产于俄国的烈性酒）","g":"[uncountable, countable]"},{"en":"a glass of vodka","cn":"一杯伏特加酒","g":"[countable]","ex":{"en":"I'll have a vodka and lime.","cn":"我要喝一杯来檬伏特加。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"伏特加（一种烈性酒）","en":"Vodka is a strong, clear, alcoholic drink."}]},"media":{"uk":"media/uk/vodka__gb_1.mp3","us":"media/us/vodka__us_1.mp3"},"examples":[{"en":"I'll have a vodka and lime.","cn":"我要喝一杯酸橙伏特加。"}]},"vocational":{"media":{"uk":"media/uk/vocational__gb_1.mp3","us":"media/us/vocational__us_1.mp3"},"oxford":{"phon":"vəʊˈkeɪʃənl","pos":"adjective","senses":[{"en":"connected with the skills, knowledge, etc. that you need to have in order to do a particular job","cn":"职业的；职业技术的；业务知识的","ex":{"en":"vocational education/qualifications/training","cn":"职业教育／资格／培训"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"职业的;职业技术的","en":"Vocational training and skills are the training and skills needed for a particular job or profession.","ex":{"en":"...a course designed to provide vocational training in engineering","cn":"工程学的职业培训课程"}}]},"examples":[{"en":"vocational education/qualifications/training","cn":"职业教育/资格/培训"},{"en":"vocational qualifications","cn":"职业资格"}]},"voting":{"oxford":{"phon":"ˈvəʊtɪŋ","pos":"noun","senses":[{"en":"the action of choosing somebody/something in an election or at a meeting","cn":"投票；选举；表决","ex":{"en":"He was eliminated in the first round of voting.","cn":"他在第一轮投票中被淘汰。"}}]},"media":{"uk":"media/uk/voting__gb_1.mp3","us":"media/us/voting__us_1.mp3"},"examples":[{"en":"Voting will take place on May 1.","cn":"投票将于 5 月 1 日进行。"},{"en":"He was eliminated in the first round of voting.","cn":"他在第一轮投票中被淘汰。"}],"base":"vote"},"volatile":{"media":{"uk":"media/uk/volatile__gb_1.mp3","us":"media/us/volatile__us_1.mp3"},"oxford":{"phon":"ˈvɒlətaɪl","pos":"adjective","senses":[{"en":"changing easily from one mood to another","cn":"易变的；无定性的；无常性的","lab":"often disapproving","ex":{"en":"a highly volatile personality","cn":"反复无常的个性"}},{"en":"likely to change suddenly; easily becoming dangerous","cn":"可能急剧波动的；不稳定的；易恶化的","ex":{"en":"This is a highly volatile situation from which riots might develop.","cn":"现在局势极不稳定，有可能发展成动乱。"}},{"en":"that changes easily into a gas","cn":"易挥发的；易发散的","lab":"specialist","ex":{"en":"Petrol is a volatile substance.","cn":"汽油是挥发性物质。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易变的;动荡不定的;反复无常的","en":"A situation that is volatile is likely to change suddenly and unexpectedly.","ex":{"en":"There have been riots before and the situation is volatile","cn":"以前曾发生过暴乱，现在局势不太稳定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）易变的，情绪无常性的","en":"If someone is volatile, their mood often changes quickly.","ex":{"en":"He accompanied the volatile actress to Hollywood the following year","cn":"第二年他陪着这位情绪无常的女演员去了好莱坞。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（液体等物质）易挥发的，易发散的","en":"A volatile liquid or substance is one that will quickly change into a gas.","ex":{"en":"It's thought that the blast occurred when volatile chemicals exploded.","cn":"人们认为，易挥发的化学物质爆炸时产生了冲击波。"}}]},"examples":[{"en":"a highly volatile situation from which riots might develop","cn":"可能会出现动乱的极不稳定的局势"},{"en":"Petrol is a volatile substance.","cn":"汽油是挥发性物质。"}]},"volunteering":{"lemma":"volunteer","media":{"uk":"media/uk/volunteer__gb_1.mp3","us":"media/us/volunteer__us_1.mp3"}},"volcanoes":{"lemma":"volcano"},"vocal":{"media":{"uk":"media/uk/vocal__gb_1.mp3","us":"media/us/vocal__us_1.mp3"},"oxford":{"phon":"ˈvəʊkl","pos":"adjective","senses":[{"en":"connected with the voice","cn":"嗓音的；发声的","g":"[only before noun]","ex":{"en":"vocal music","cn":"声乐"}},{"en":"telling people your opinions or protesting about something loudly and with confidence","cn":"大声表达的；直言不讳的","ex":{"en":"He has been very vocal in his criticism of the government's policy.","cn":"他对政府政策的批评一直是直言不讳。"}},{"en":"the part of a piece of music that is sung, rather than played on a musical instrument","cn":"（乐曲中的）歌唱部分，声乐部分","ex":{"en":"backing vocals","cn":"伴唱"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大声说出的;直言不讳的;激烈表达意见的","en":"You say that people are vocal when they speak forcefully about something that they feel strongly about.","ex":{"en":"He has been very vocal in his displeasure over the results","cn":"他直言不讳地表达了他对结果的不满。"}},{"pos":"ADJ 形容词","cn":"嗓音的;发声的;（尤指）歌唱的","en":"Vocal means involving the use of the human voice, especially in singing.","ex":{"en":"...a wider range of vocal styles.","cn":"更多样的歌唱风格"}}]},"examples":[{"en":"He has been very vocal in his criticism of the government's policy.","cn":"他对政府政策的批评一直是直言不讳。"},{"en":"In this recording Armstrong himself is on vocals.","cn":"在这个录音中阿姆斯特朗亲自领唱。"}]},"vote":{"oxford":{"phon":"vəʊt","pos":"noun","senses":[{"en":"a formal choice that you make in an election or at a meeting in order to choose somebody or decide something","cn":"选票；票","g":"[countable]","ex":{"en":"to win/lose votes","cn":"赢得／失去选票"}},{"en":"an occasion when a group of people vote on something","cn":"投票；选举；表决","g":"[countable]","ex":{"en":"to win/lose a vote","cn":"赢得／输掉选举"}},{"en":"the right to vote, especially in political elections","cn":"（尤指政治选举中的）投票权，选举权，表决权","g":"[singular]","ex":{"en":"In Britain and the US, people get the vote at 18.","cn":"在英国和美国，国民 18 岁开始有选举权。"}},{"en":"the total number of votes in an election","cn":"投票总数；选票总数","g":"[singular]","ex":{"en":"She obtained 40% of the vote.","cn":"她获得 40% 的选票。"}},{"en":"the vote given by a particular group of people, or for a particular party, etc.","cn":"（某一群体的）投票总数；（某一政党等的）得票总数","g":"[singular]","ex":{"en":"the student vote","cn":"学生的投票总数"}},{"en":"to show formally by marking a paper, raising your hand, using a voting machine, etc. which person you want to win an election, or which plan or idea you support","cn":"投票；表决","g":"[intransitive, transitive]","lab":"especially North American English","ex":{"en":"How did you vote at the last election?","cn":"在上次选举中你是怎么投的票？"},"pos":"verb"},{"en":"to choose somebody/something for a position or an award by voting","cn":"选出，推举（某人担任某职）；表决（授奖给某人）","g":"[transitive, usually passive]","ex":{"en":"He was voted most promising new director.","cn":"他当选为最有前途的新导演。"},"pos":"verb"},{"en":"to say that something is good or bad","cn":"表明，认为，公认（某事好或坏）","g":"[transitive, usually passive]","ex":{"en":"The event was voted a great success.","cn":"大家认为这项活动很成功。"},"pos":"verb"},{"en":"to agree to give somebody/yourself something by voting","cn":"投票同意","g":"[transitive]","ex":{"en":"The directors have just voted themselves a huge pay increase.","cn":"董事们刚刚投票同意给他们自己大幅度提高工资。"},"pos":"verb"},{"en":"to suggest something or support a suggestion that somebody has made","cn":"提议；建议；支持（建议）","g":"[transitive]","ex":{"en":"I vote (that) we go out to eat.","cn":"我提议我们到外面去吃饭。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"选票;票","en":"A vote is a choice made by a particular person or group in a meeting or an election.","ex":{"en":"He walked to the local polling centre to cast his vote","cn":"他走到当地的投票中心投了票。"}},{"pos":"N-COUNT 可数名词","cn":"投票;表决","en":"A vote is an occasion when a group of people make a decision by each person indicating his or her choice. The choice that most people support is accepted by the group.","ex":{"en":"Why do you think we should have a vote on that?","cn":"为什么你认为我们应该对那件事进行表决？"}},{"pos":"N-SING 单数名词","cn":"投票总数;选票总数","en":"The vote is the total number of votes or voters in an election, or the number of votes received or cast by a particular group.","ex":{"en":"Opposition parties won about fifty-five per cent of the vote","cn":"反对党大约赢得了55％的选票。"}},{"pos":"N-SING 单数名词","cn":"投票权;选举权;表决权","en":"If you have the vote in an election, or have a vote in a meeting, you have the legal right to indicate your choice.","ex":{"en":"And of course we didn't even have the vote, did we?","cn":"当然了，我们连投票权都没有，不是吗？"}},{"pos":"VERB 动词","cn":"投票;表决;选举","en":"When you vote, you indicate your choice officially at a meeting or in an election, for example by raising your hand or writing on a piece of paper.","ex":{"en":"Two-thirds of the national electorate had the chance to vote in these elections","cn":"全国选民的2/3有机会在这些选举中投票。"}},{"pos":"VERB 动词","cn":"投…的票；投（赞成或反对）票","en":"If you vote a particular political party or leader, or vote yes or no, you make that choice with the vote that you have.","ex":{"en":"52.5% of those questioned said they'd vote Labour","cn":"52.5％的受访者表示他们会投工党的票。"}},{"pos":"VERB 动词","cn":"（通过投票）决定给予（资助），同意提供（款项）","en":"If a government or other organization votes money for something or to do something, they decide to spend the money in that way.","ex":{"en":"The General Court had voted $2,500 for a monument to be erected to his memory","cn":"州议会投票决定拨款2,500美元为他建一座纪念碑。"}},{"pos":"VERB 动词","cn":"投票评选","en":"If people vote someone a particular title, they choose that person to have that title.","ex":{"en":"His class voted him the man 'who had done the most for Yale.'","cn":"他被班里评选为“为耶鲁作出最大贡献”的人。"}},{"pos":"PHRASE 短语","cn":"以退席（或退出组织）表示反对","en":"If you vote with your feet, you show that you do not support something by leaving the place where it is happening or leaving the organization that is supporting it.","ex":{"en":"Thousands of citizens are already voting with their feet, and leaving the country","cn":"成千上万的公民正准备离开这个国家，以这一举动表示反对。"}},{"pos":"PHRASE 短语","cn":"我认为;我建议;我提议","en":"If you say 'vote that' a particular thing should happen, you are suggesting that this is what should happen.","ex":{"en":"I vote that we all go to Holland immediately","cn":"我建议我们全都立刻前往荷兰。"}},{"pos":"PHRASE 短语","cn":"一人一票制","en":"One man one vote or one person one vote is a system of voting in which every person in a group or country has the right to cast their vote, and in which each individual's vote is counted and has equal value.","ex":{"en":"Mr Gould called for a move towards 'one man one vote'","cn":"古尔德先生号召采取“一人一票制”。"}},{"pos":"","cn":"","en":"相关词组：vote down vote in vote out"}]},"media":{"uk":"media/uk/vote__gb_1.mp3","us":"media/us/vote__us_1.mp3"},"examples":[{"en":"The Green candidate won over 3 000 of the 14 000 votes cast.","cn":"绿党候选人在 14 000 张投票总数中获得了 3 000 多张选票。"},{"en":"There were 21 votes for and 17 against the motion, with 2 abstentions.","cn":"这项动议有 21 票赞成，17 票反对，2 票弃权。"}]},"vocabulary":{"media":{"uk":"media/uk/vocabulary__gb_1.mp3","us":"media/us/vocabulary__us_1.mp3"},"oxford":{"phon":"vəˈkæbjələri","pos":"noun","senses":[{"en":"all the words that a person knows or uses","cn":"（某人掌握或使用的）词汇，词汇量","g":"[countable, uncountable]","ex":{"en":"to have a wide/limited vocabulary","cn":"词汇量大／有限"}},{"en":"all the words in a particular language","cn":"（某一语言的）词汇，词汇量","g":"[countable]","ex":{"en":"When did the word ‘bungalow’ first enter the vocabulary?","cn":"bungalow 一词何时进入（英语）词汇中的？"}},{"en":"the words that people use when they are talking about a particular subject","cn":"（某学科中所使用的）词汇","g":"[uncountable, countable]","ex":{"en":"The word has become part of advertising vocabulary.","cn":"这个单词已经成了广告用语。"}},{"en":"a list of words with their meanings, especially in a book for learning a foreign language","cn":"（尤指外语教科书中附有释义的）词汇表","g":"[countable]","lab":"informal","ex":{"en":"Write it down in your vocab book.","cn":"把它写在你的词汇本上。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（某人所掌握的）词汇,词汇量","en":"Your vocabulary is the total number of words you know in a particular language.","ex":{"en":"His speech is immature, his vocabulary limited","cn":"他说话很幼稚，使用的词汇有限。"}},{"pos":"N-SING 单数名词","cn":"(某一语言的）词汇，词汇量","en":"The vocabulary of a language is all the words in it.","ex":{"en":"...a new word in the German vocabulary.","cn":"德语词汇中的一个新词"}},{"pos":"N-VAR 可变名词","cn":"专业词汇","en":"The vocabulary of a subject is the group of words that are typically used when discussing it.","ex":{"en":"...the vocabulary of natural science.","cn":"自然科学词汇"}}]},"examples":[{"en":"The word ‘failure’ is not in his vocabulary (= for him, failure does not exist).","cn":"在他的词典中没有“失败”这个词。"},{"en":"When did the word ‘bungalow’ first enter the vocabulary? * bungalow","cn":"一词何时进入（英语）词汇中的？"}]},"void":{"media":{"uk":"media/uk/void__gb_1.mp3","us":"media/us/void__us_1.mp3"},"oxford":{"phon":"vɔɪd","pos":"noun","senses":[{"en":"a large empty space","cn":"空间；空白；真空；空虚","ex":{"en":"Below him was nothing but a black void.","cn":"他下面只是一片漆黑。"}},{"en":"a feeling of being empty, caused by the loss of somebody/something","cn":"（因失去某人或某事物而产生的）空虚感，寂寞感，缺失感","ex":{"en":"The void left by his mother's death was never filled.","cn":"他母亲死后留下的空虚感永远没能填补上。"}},{"en":"completely without something","cn":"缺乏；没有","lab":"formal","ex":{"en":"The sky was void of stars.","cn":"天空没有一颗星星。"},"pos":"adjective"},{"en":"not correct or legally valid","cn":"无效的","lab":"law","ex":{"en":"The agreement was declared void.","cn":"该协议已宣布无效。"},"pos":"adjective"},{"en":"empty","cn":"空的；空空如也的","lab":"formal","ex":{"en":"void spaces","cn":"空位"},"pos":"adjective"},{"en":"to state officially that something is no longer correct or legally valid","cn":"使无效；宣布…作废；取消","lab":"law","pos":"verb"},{"en":"to empty waste matter from the bladder or bowels","cn":"排泄，排放（大小便）","lab":"formal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"空白;空虚感","en":"If you describe a situation or a feeling as a void, you mean that it seems empty because there is nothing interesting or worthwhile about it.","ex":{"en":"His death has left a void in the cricketing world which can never be filled.","cn":"他的死给板球界留下一个永远无法填补的空白。"}},{"pos":"N-COUNT 可数名词","cn":"空间;真空;空虚","en":"You can describe a large or frightening space as a void .","ex":{"en":"He stared into the dark void where the battle had been fought","cn":"他凝望着那片漆黑的空旷之地，那次战役就是在这里进行的。"}},{"pos":"ADJ 形容词","cn":"无价值的;无用的;无效的","en":"Something that is void or null and void is officially considered to have no value or authority.","ex":{"en":"The original elections were declared void by the former military ruler","cn":"前军事领导人宣布最初的选举无效。"}},{"pos":"ADJ 形容词","cn":"缺乏的;没有的","en":"If you are void of something, you do not have any of it.","ex":{"en":"He rose, his face void of emotion as he walked towards the door","cn":"他站起来，面无表情地朝门口走去。"}},{"pos":"VERB 动词","cn":"使无效;宣布…作废;取消","en":"To void something means to officially say that it is not valid.","ex":{"en":"The Supreme Court threw out the confession and voided his conviction for murder.","cn":"最高法院驳回了供词，宣布他谋杀罪名不成立。"}}]},"examples":[{"en":"( figurative ) The void left by his mother's death was never filled.","cn":"他母亲死后留下的空虚感永远没能填补上。"},{"en":"Below him was nothing but a black void.","cn":"他下面只是一片漆黑。"}]},"volt":{"oxford":{"phon":"vəʊlt","pos":"noun","senses":[{"en":"a unit for measuring the force of an electric current","cn":"伏，伏特（电压单位）","ex":{"en":"a high security fence with 5 000 volts passing through it","cn":"通有 5 000 伏电流的森严铁丝网"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伏特，伏（电压单位）","en":"A volt is a unit used to measure the force of an electric current."}]},"media":{"uk":"media/uk/volt__gb_1.mp3","us":"media/us/volt__us_1.mp3"},"examples":[{"en":"a high security fence with 5 000 volts passing through it","cn":"有 5 000 伏电流通过的森严铁丝网"}]},"vomit":{"oxford":{"phon":"ˈvɒmɪt","pos":"verb","senses":[{"en":"to bring food from the stomach back out through the mouth","cn":"呕；吐；呕吐","ex":{"en":"The smell made her want to vomit.","cn":"那气味让她想吐。"}},{"en":"food from the stomach brought back out through the mouth","cn":"呕吐物","ex":{"en":"You must ensure that an unconscious person does not choke on their own vomit.","cn":"你必须确保昏迷者不被自己的呕吐物给噎着。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吐;呕吐","en":"If you vomit, food and drink comes back up from your stomach and out through your mouth.","ex":{"en":"Any product made from cow's milk made him vomit","cn":"任何乳制品都会让他呕吐。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"呕吐物","en":"Vomit is partly digested food and drink that has come back up from someone's stomach and out through their mouth."}]},"media":{"uk":"media/uk/vomit__gb_1.mp3","us":"media/us/vomit__us_1.mp3"},"examples":[{"en":"He had vomited up his supper.","cn":"他把晚饭吃的东西都吐了出来。"},{"en":"The smell made her want to vomit.","cn":"那气味使得她想要吐。"}]},"volunteers":{"lemma":"volunteer"},"voices":{"lemma":"voice"},"voyeuristic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有窥淫癖的","en":"Voyeuristic behaviour involves getting sexual pleasure from secretly watching other people having sex or taking their clothes off."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好刺探他人隐私的","en":"If you describe someone's behaviour as voyeuristic, you disapprove of them because you think they enjoy watching other people's suffering or problems.","ex":{"en":"We as a society are growing more commercial and voyeuristic all the time.","cn":"我们的社会正变得越来越商业化，更好打探别人隐私。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gets sexual pleasure from secretly watching other people’s sexual activities","cn":""},{"en":"someone who enjoys watching other people’s private behaviour or suffering","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be voyeuristic is to be sexually excited by watching others. Peeping Toms are voyeuristic ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld44voyeur.mp3","us":"media/ldoce/hwd/ame/e/voyeur.mp3"},"examples":[{"en":"a voyeuristic interest in other people's lives","cn":"对他人生活怀有窥秘癖的兴趣"}],"oxford":{"phon":"ˌvɔɪəˈrɪstɪk","pos":"adjective","senses":[{"en":"getting pleasure by secretly watching people who are wearing no clothes or having sex","cn":"窥阴癖者（喜欢偷窥他人裸体或性交）"},{"en":"gaining pleasure from watching the problems and private lives of others","cn":"刺探隐秘者（喜欢刺探他人的问题或私生活）","ex":{"en":"a voyeuristic interest in other people’s lives","cn":"窥探他人生活的癖好"}}]}},"volleyball":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"排球","en":"Volleyball is a game in which two teams hit a large ball with their hands backwards and forwards over a high net. If you allow the ball to touch the ground, the other team wins a point."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a game in which two teams use their hands to hit a ball over a high net","cn":"排球(运动)"}]},"media":{"uk":"media/ldoce/hwd/bre/3/volleyball0205.mp3","us":"media/ldoce/hwd/ame/5/volleyball.mp3"},"oxford":{"phon":"ˈvɒlibɔːl","pos":"noun","senses":[{"en":"a game in which two teams of six players use their hands to hit a large ball backwards and forwards over a high net while trying not to let the ball touch the ground on their own side","cn":"排球运动"}]}},"vouchsafe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"赐予;给予;惠予","en":"If you are vouchsafed something or it is vouchsafed to you, you are given or granted it.","ex":{"en":"As we approached the summit we were vouchsafed a rare vision","cn":"快到山顶时，我们有幸看到了难得一见的景象。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to promise or offer something, or tell someone something that they can be certain is the truth","cn":"惠予﹐赐予﹔允诺"}]},"vocab":{"pos":"v","senses":[{"en":"Vouchsafe is a verb meaning to offer something in a condescending way. You might vouchsafe to your brother the secret to your key lime pie recipe."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41vouchsafe.mp3","us":"media/ldoce/hwd/ame/b/vouchsafe.mp3"},"examples":[{"en":"He vouchsafed to me certain family secrets.","cn":"他让我知道了某些家庭秘密。"}],"oxford":{"phon":"ˌvaʊtʃˈseɪf","pos":"verb","senses":[{"en":"to give, offer or tell something to somebody, especially in order to give them a special advantage","cn":"赐予，给予，告知（尤指为给特别的好处）","ex":{"en":"He vouchsafed to me certain family secrets.","cn":"他让我知道了某些家庭秘密。"}}]}},"vocation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"使命;天职","en":"If you have a vocation, you have a strong feeling that you are especially suited to do a particular job or to fulfil a particular role in life, especially one which involves helping other people.","ex":{"en":"It could well be that he has a real vocation","cn":"很可能他是找到了自己真正的使命。"}},{"pos":"N-VAR 可变名词","cn":"（认为特别适合自己的）工作，职业","en":"If you refer to your job or profession as your vocation, you feel that you are particularly suited to it.","ex":{"en":"Her vocation is her work as an actress","cn":"她的职业就是当演员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the work that you do regularly in order to earn money, especially when you work for an employer","cn":""},{"en":"work that someone does regularly to earn money, either by working for an employer or working for themselves","cn":""},{"en":"work such as law, medicine, or teaching, for which you need special training and education","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Unless you can find someone to pay you to sip fancy tropical drinks on the beach, your vocation is not likely to be a \"vacation.\" Rather, the word means something you know how to do––or what you do for a living."}]},"collocations":{"phrases":["ADJ. real, true | religious","VERB + VOCATION find She struggled for years to find her true vocation. | have | follow, pursue He is desperate to pursue his vocation as an","PREP. ~ for She seems to have a vocation for healing. | ~ to a vocation to the priesthood","PHRASES a sense of vocation This is a job that demands a sense of vocation."]},"media":{"uk":"media/ldoce/hwd/bre/3/vocation0205.mp3","us":"media/ldoce/hwd/ame/d/vocation.mp3"},"examples":[{"en":"Nursing is not just a job — it's a vocation.","cn":"护理不仅仅是一项工作，而且还是一种职业。"},{"en":"She believes that she has found her true vocation in life.","cn":"她相信自己找到了真正适合自己的生活方式。"}],"oxford":{"phon":"vəʊˈkeɪʃn","pos":"noun","senses":[{"en":"a type of work or way of life that you believe is especially suitable for you","cn":"（认为特别适合自己的）工作，职业，生活方式","g":"[countable]","lab":"British English","ex":{"en":"Nursing is not just a job—it's a vocation.","cn":"护理不仅仅是一项工作，而且还是一种职业。"}},{"en":"a belief that a particular type of work or way of life is especially suitable for you","cn":"（认为某种工作或生活方式特别适合自己的）信心，使命感","g":"[countable, uncountable]","ex":{"en":"He has a vocation for teaching.","cn":"他是教书的材料。"}},{"en":"a belief that you have been chosen by God to be a priest or nun","cn":"圣召；神召","g":"[countable, uncountable]","ex":{"en":"He spoke about his vocation to the priesthood.","cn":"他谈到了自己蒙圣召成为司铎。"}}]}},"vocalist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（流行乐队中的）歌手","en":"A vocalist is a singer who sings with a pop group.","ex":{"en":"He and Carla Torgerson take turns as the band's lead vocalist.","cn":"他和卡拉·托格森轮流担当乐队的主唱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who sings, especially as their job","cn":""},{"en":"a singer in a group that plays popular music","cn":""},{"en":"a large group of singers who regularly sing in a church or school or with a group of musicians","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/vocalist0205.mp3","us":"media/ldoce/hwd/ame/2/vocalist.mp3"},"examples":[{"en":"a lead/guest/backing vocalist","cn":"领唱/特邀/伴唱歌手"}],"oxford":{"phon":"ˈvəʊkəlɪst","pos":"noun","senses":[{"en":"a singer, especially in a pop, rock or jazz band","cn":"（尤指流行音乐、摇滚乐或爵士乐乐队的）歌手，歌唱者","ex":{"en":"a lead/guest/backing vocalist","cn":"领唱／特邀／伴唱歌手"}}]}},"volition":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自愿选择;自行决定","en":"Your volition is the power you have to decide something for yourself.","ex":{"en":"We like to think that everything we do and everything we think is a product of our volition","cn":"我们常常认为我们所做和所想的一切都出自自己的意愿。"}},{"pos":"PHRASE 短语","cn":"出于自愿","en":"If you do something of your own volition, you do it because you have decided for yourself that you will do it and not because someone else has told you to do it.","ex":{"en":"Makin said Mr Coombes had gone to the police of his own volition.","cn":"梅金说库姆斯先生是主动去投案的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do something of your own volition, you do it because you want to, not because you are forced to","cn":"出于自愿"},{"en":"the power to choose or decide something without being forced to do it","cn":"自愿选择﹔自行决断"}]},"vocab":{"pos":"n","senses":[{"en":"When you do something voluntarily, you do it of your own volition, or will. Doing something willingly, or because you agree to it, is doing something of your own volition."}]},"media":{"uk":"media/ldoce/hwd/bre/8/volition0205.mp3","us":"media/ldoce/hwd/ame/a/volition.mp3"},"examples":[{"en":"They left entirely of their own volition (= because they wanted to).","cn":"他们完全是自愿离开的。"},{"en":"Helena left the company of her own volition.","cn":"海伦娜是自愿离开公司的。"}],"oxford":{"phon":"vəˈlɪʃn","pos":"noun","senses":[{"en":"the power to choose something freely or to make your own decisions","cn":"意志力；自愿选择；自行决断","ex":{"en":"They left entirely of their own volition (= because they wanted to).","cn":"他们完全是自愿离开的。"}}]}},"vocalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"说出","en":"If you vocalize a feeling or an idea, you express it in words.","ex":{"en":"Archbishop Hunthausen also vocalized his beliefs that women and homosexuals should be more active in the church.","cn":"大主教亨特豪森也发言阐述了他的看法：妇女和同性恋者应该更积极地参与教堂事务。"}},{"pos":"VERB 动词","cn":"发声;（尤指）唱","en":"When you vocalize a sound, you use your voice to make it, especially by singing it.","ex":{"en":"In India and Bali students learn to vocalize music before ever picking up instruments.","cn":"在印度和巴厘岛，学生们在开始学习乐器之前要先学习唱歌。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a sound or sounds with your voice","cn":"发声﹔说(话)﹔唱(歌)"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44vocalize.mp3","us":"media/ldoce/hwd/ame/9/ld44vocalize.mp3"},"examples":[{"en":"Showing children pictures sometimes helps them to vocalize their ideas.","cn":"让儿童看图画有时有助于他们用言语表达思想。"},{"en":"Your baby will begin to vocalize long before she can talk.","cn":"你的宝宝远在会说话之前就会开始咿呀发声。"}],"oxford":{"phon":"ˈvəʊkəlaɪz","pos":"verb","senses":[{"en":"to use words to express something","cn":"用言语表达","g":"[transitive]","ex":{"en":"Showing children pictures sometimes helps them to vocalize their ideas.","cn":"让儿童看图画有时有助于他们用言语表达思想。"}},{"en":"to say or sing sounds or words","cn":"说（话）；唱（歌）；哼；发声","g":"[intransitive, transitive]","ex":{"en":"Your baby will begin to vocalize long before she can talk.","cn":"你的宝宝在她会说话前很早就要开始咿呀发声了。"}}]}},"vow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发誓;起誓;立誓","en":"If you vow to do something, you make a serious promise or decision that you will do it.","ex":{"en":"While many models vow to go back to college, few do","cn":"很多模特发誓要重回大学校园，但很少有人做到。"}},{"pos":"N-COUNT 可数名词","cn":"誓言;诺言","en":"A vow is a serious promise or decision to do a particular thing.","ex":{"en":"I made a silent vow to be more careful in the future","cn":"我暗暗发誓，日后要倍加小心。"}},{"pos":"N-COUNT 可数名词","cn":"誓词;誓约;宣言","en":"Vows are a particular set of serious promises, such as the promises two people make when they are getting married.","ex":{"en":"I took my marriage vows and kept them.","cn":"我结婚时许下誓言，并一直信守。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that you will definitely do or provide something, which may not be reliable","cn":""},{"en":"a public or official promise to do a particular thing in the future","cn":""},{"en":"a very serious promise to do something or not to do something that you choose to make","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To vow is to make an earnest promise or pledge. People getting married often vow to stick together “till death do us part,” while a presidential candidate might vow to lower taxes."}]},"collocations":{"phrases":["ADJ. formal, solemn | marriage, wedding | monastic, religious | final She left the convent before taking her final vows.","VERB + VOW make, take He made a vow to avenge his father's death. | keep She kept her vow of silence until she died. | break Nothing will pe","PREP. ~ of a vow of poverty"]},"media":{"uk":"media/ldoce/hwd/bre/5/vow_v0205.mp3","us":"media/ldoce/hwd/ame/0/vow1.mp3"},"examples":[{"en":"She vowed never to speak to him again.","cn":"她发誓再也不和他说话了。"},{"en":"‘I'll be back,’ she vowed. “","cn":"我会回来的。”她发誓道。"}],"oxford":{"phon":"vaʊ","pos":"verb","senses":[{"en":"to make a formal and serious promise to do something or a formal statement that is true","cn":"起誓；立誓；发誓","ex":{"en":"She vowed never to speak to him again.","cn":"她发誓再也不和他说话了。"}},{"en":"a formal and serious promise, especially a religious one, to do something","cn":"（尤指宗教的）誓，誓言，誓约","lab":"especially North American English","ex":{"en":"to make/take a vow","cn":"立誓；发誓"},"pos":"noun"}]}},"voracious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贪吃的;狼吞虎咽的;贪婪的;渴求的","en":"If you describe a person, or their appetite for something, as voracious, you mean that they want a lot of something.","ex":{"en":"Joseph Smith was a voracious book collector.","cn":"约瑟夫·史密斯是个如饥似渴的藏书家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who enjoys reading and reads a lot","cn":""},{"en":"someone who spends a lot of time reading","cn":""},{"en":"someone who is well-read has read a lot of books, often the most important or famous books, and has learned a lot of information from them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Voracious is an adjective used to describe a wolflike appetite. It might be a craving for food or for something else, such as power, but the word usually denotes an unflattering greediness."}]},"media":{"uk":"media/ldoce/hwd/bre/2/voracious0205.mp3","us":"media/ldoce/hwd/ame/2/voracious.mp3"},"examples":[{"en":"a boy with a voracious and undiscriminating appetite for facts","cn":"一个如饥似渴地寻求事实的男孩"},{"en":"a voracious reader","cn":"求知欲极强的读者"}],"oxford":{"phon":"vəˈreɪʃəs","pos":"adjective","senses":[{"en":"eating or wanting large amounts of food","cn":"饭量大的；贪吃的；狼吞虎咽的","ex":{"en":"a voracious eater","cn":"贪吃的人"}},{"en":"wanting a lot of new information and knowledge","cn":"（对信息、知识）渴求的；求知欲强的","ex":{"en":"a voracious reader","cn":"求知欲极强的读者"}}]}},"voodoo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（西印度群岛人、尤其是海地人信奉的）伏都教","en":"Voodoo is a form of religion involving magic which is practised by some people in the West Indies, especially Haiti."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the power to make impossible things happen, by saying special words or doing special actions","cn":""},{"en":"the use of magic, usually to do bad things","cn":""},{"en":"a special set of words or actions that are used to make something happen by magic","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/voodoo0205.mp3","us":"media/ldoce/hwd/ame/3/voodoo.mp3"},"oxford":{"phon":"ˈvuːduː","pos":"noun","senses":[{"en":"a religion that is practised especially in Haiti and involves magic and witchcraft","cn":"伏都教，巫毒教（尤指在海地奉行的一种宗教，涉及魔法和巫术）"}]}},"voluptuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体态丰满的;性感的","en":"If you describe a woman as voluptuous, you mean that she has large breasts and hips and is considered attractive in a sexual way.","ex":{"en":"...a voluptuous, well-rounded lady with glossy black hair.","cn":"头发乌黑亮丽、身材丰满性感的女士"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"给人以感官享受的;满足感官的","en":"Something that is voluptuous gives you a great deal of pleasure from the rich way it is experienced through your senses.","ex":{"en":"'Opium' is a provocative, sensual, and voluptuous fragrance which makes all your senses vibrate.","cn":"“鸦片”是一种刺激性的、能引起感官快感的香料，能使你所有的感官兴奋起来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attractive to people, either because of your body, your good looks, or attractive personality","cn":""},{"en":"someone who is attractive has a personality or appearance that makes other people sexually attracted to them","cn":""},{"en":"someone's appearance, behaviour, or personality that makes them sexually attractive","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Voluptuous describes a woman that's large — but in all the right places. Voluptuous is a curvy compliment."}]},"media":{"uk":"media/ldoce/hwd/bre/c/voluptuous0205.mp3","us":"media/ldoce/hwd/ame/0/voluptuous.mp3"},"examples":[{"en":"a voluptuous woman","cn":"体态丰满的女人"},{"en":"a voluptuous body","cn":"丰满性感的身体"}],"oxford":{"phon":"vəˈlʌptʃuəs","pos":"adjective","senses":[{"en":"having large breasts and hips in a way that is sexually attractive","cn":"（女人）性感的，肉感的，丰满的","lab":"formal","ex":{"en":"a voluptuous woman","cn":"体态丰满的女人"}},{"en":"giving you physical pleasure","cn":"令人舒服的；舒适的","lab":"literary","ex":{"en":"voluptuous perfume","cn":"芬芳馥郁的香水"}}]}},"voiceless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（发）清音的","en":"A voiceless speech sound is one that is produced without vibration of the vocal cords.","ex":{"en":"...the voiceless 'th'.","cn":"发清音的th"}},{"pos":"ADJ 形容词","cn":"失语的;不能说话的","en":"Someone who is voiceless is unable to speak.","ex":{"en":"His voiceless lips formed the words 'Thank you'.","cn":"他发不出声音来，翕动着嘴唇说了“谢谢你”这几个字。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to get your opinions or concerns noticed by people in power","cn":"不能表达观点的﹐无发言权的"},{"en":"voiceless sounds are made without using the vocal cords . For example, /p/ and /k/ are voiceless consonant s . 〔","cn":"音〕清的〔如/p/和/k/为清辅音〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41voiceless.mp3","us":"media/ldoce/hwd/ame/a/voiceless.mp3"},"examples":[{"en":"The vast majority of our people feel ignored and voiceless.","cn":"我们人民中的绝大多数觉得受到了忽视﹐而且没有发言权。"}],"oxford":{"phon":"ˈvɔɪsləs","pos":"adjective","senses":[{"en":"produced without moving your vocal cords. In English the consonants /p t k tʃ f θ s ʃ h/ are voiceless.","cn":"清音的"}]}},"voile":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"巴里纱（用于制作女装的薄纱）","en":"Voile is thin material which is used for making women's clothing, for example dresses, blouses, and scarves."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very light almost transparent cloth made of cotton, wool, or silk","cn":"巴里纱〔一种很轻﹑近乎透明的布料﹐用棉﹑毛或真丝织成〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41voile.mp3","us":"media/ldoce/hwd/ame/c/voile.mp3"},"oxford":{"phon":"vɔɪl","pos":"noun","senses":[{"en":"a type of cloth made of cotton, wool or silk that you can almost see through, used for making clothes and curtains","cn":"巴里纱（由棉、毛或丝制成，近乎透明，用于制作衣服和窗帘）"}]}},"voter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"选民;投票人;选举人","en":"Voters are people who have the legal right to vote in elections, or people who are voting in a particular election.","ex":{"en":"The turnout was at least 62 percent of registered voters","cn":"至少有62％的登记选民参加了投票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who votes in a political election","cn":""},{"en":"all the people who can vote in a country or area","cn":""},{"en":"someone who has the right to vote in a political election, or who votes in a particular election","cn":"选举人﹐投票人﹐选民﹔有投票权的人"}]},"collocations":{"phrases":["ADJ. eligible, registered Only a quarter of registered voters actually voted in the election. | proxy | overseas | floating, uncommitted, un","VERB + VOTER woo attempts to woo undecided voters | persuade | convince | urge, warn | influence","VOTER + VERB choose sb, favour sb, pick sb, prefer sb In this election, voters chose candidates who promised economic security. | participat","VOTER + NOUN turnout Voter turnout was very low. | registration | disillusionment | intimidation The Opposition alleged voter intimidation b"]},"media":{"uk":"media/ldoce/hwd/bre/6/voter0205.mp3","us":"media/ldoce/hwd/ame/5/voter.mp3"},"examples":[{"en":"Only 60% of eligible voters actually used their vote.","cn":"只有 60% 的符合资格的投票人行使了选举权。"},{"en":"A clear majority of voters were in favour of the motion.","cn":"绝大多数选民赞成这一动议。"}],"oxford":{"phon":"ˈvəʊtə(r)","pos":"noun","senses":[{"en":"a person who votes or has the right to vote, especially in a political election","cn":"（尤指政治性选举的）投票人，选举人，有选举权的人","lab":"especially North American English","ex":{"en":"A clear majority of voters were in favour of the motion.","cn":"绝大多数选民赞成这一动议。"}}]}},"voyeurism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"窥淫癖","en":"Voyeurism is the practice of getting sexual pleasure by secretly watching other people having sex or taking their clothes off."},{"pos":"N-UNCOUNT 不可数名词","cn":"刺探他人隐私的行为","en":"If you describe someone's behaviour as voyeurism, you disapprove of them because you think they enjoy watching other people's suffering or problems.","ex":{"en":"The BBC yesterday defended a series featuring dramatic crime reconstructions against suggestions of voyeurism.","cn":"英国广播公司昨日为一部生动再现犯罪活动的电视系列剧进行了辩护，称其并没有窥探他人隐私之嫌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gets sexual pleasure from secretly watching other people’s sexual activities","cn":""},{"en":"someone who enjoys watching other people’s private behaviour or suffering","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Voyeurism is a strange type of behavior in which someone gets turned on by watching other people, especially in sexual situations."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld44voyeur.mp3","us":"media/ldoce/hwd/ame/e/voyeur.mp3"},"oxford":{"phon":"vɔɪˈɜːrɪzəm","pos":"noun","senses":[{"en":"the practice of getting pleasure by secretly watching people who are wearing no clothes or having sex","cn":"窥阴癖者（喜欢偷窥他人裸体或性交）"},{"en":"pleasure gained from watching the problems and private lives of others","cn":"刺探隐秘者（喜欢刺探他人的问题或私生活）","ex":{"en":"the voyeurism inherent in this type of photography","cn":"此类摄影固有的偷窥癖"}}]}},"voltage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"电压;伏特数","en":"The voltage of an electrical current is its force measured in volts.","ex":{"en":"The systems are getting smaller and using lower voltages.","cn":"这些系统变得更小，使用的电压也更低。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"electrical force measured in volts","cn":"电压﹐伏特数"},{"en":"high/low voltage","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Voltage is a measure of electrical energy. If you've got a high- voltage personality, people may use another electrical metaphor and describe you as \"a live wire.\""}]},"collocations":{"phrases":["ADJ. high, low | constant | changing, varying | mains, supply Most house lighting runs at the full mains voltage of 240 volts. | input, outp","VERB + VOLTAGE increase, step up, turn up | decrease, step down, turn down | produce | apply A voltage is then applied across the cell elect","PREP. at a ~ The motor operates at low voltages."]},"media":{"uk":"media/ldoce/hwd/bre/f/voltage0205.mp3","us":"media/ldoce/hwd/ame/8/voltage.mp3"},"examples":[{"en":"high/low voltage","cn":"高/低压"}],"oxford":{"phon":"ˈvəʊltɪdʒ","pos":"noun","senses":[{"en":"electrical force measured in volts","cn":"电压；伏特数","ex":{"en":"high/low voltage","cn":"高压；低压"}}]}},"volley":{"collins":{"senses":[{"pos":"VERB 动词","cn":"截踢,截击(空中球)","en":"In sport, if someone volleys the ball, they hit it before it touches the ground.","ex":{"en":"He volleyed the ball spectacularly into the far corner of the net","cn":"他一脚漂亮的凌空抽射，把球踢进了球门的远角。"}},{"pos":"N-COUNT 可数名词","cn":"（子弹的）群射，齐发","en":"A volley of gunfire is a lot of bullets that travel through the air at the same time.","ex":{"en":"It's still not known how many died in the volleys of gunfire","cn":"现在还不知道有多少人在枪林弹雨中身亡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to shoot someone or something","cn":""},{"en":"when someone is shot at, and killed or injured","cn":""},{"en":"the repeated shooting of a gun or guns","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 v","senses":[{"en":"When an attacking army lets loose a barrage of bullets all at once, it's called a volley ."}]},"collocations":{"phrases":["VERB + VOLLEY fire, unleash The police fired a volley of bullets over the heads of the crowd.","PREP. ~ of 2 in sport","ADJ. backhand, cross-court, forehand (in tennis) | left-foot, right-foot (in football) | stunning, superb Williams took the set with a stunn","VERB + VOLLEY hit She hit a forehand volley into the net. | crack/crash/lash home, strike, unleash (all in football) Cole lashed home a 20-y","PREP. on the ~ Figo met the ball on the volley and scored."]},"media":{"uk":"media/ldoce/hwd/bre/8/volley_n0205.mp3","us":"media/ldoce/hwd/ame/3/volley1.mp3"},"examples":[{"en":"Police fired a volley over the heads of the crowd.","cn":"警察朝人群头顶上方射出一排子弹。"},{"en":"She faced a volley of angry questions from her mother.","cn":"她受到母亲一连串愤怒的质问。"}],"oxford":{"phon":"ˈvɒli","pos":"noun","senses":[{"en":"a hit or kick of the ball before it touches the ground","cn":"截击空中球；凌空击球（或踢球）","ex":{"en":"She hit a forehand volley into the net.","cn":"她正手截击球未过网。"}},{"en":"a lot of bullets, stones, etc. that are fired or thrown at the same time","cn":"（子弹的）群射，齐发；（石块的）齐投","ex":{"en":"A volley of shots rang out.","cn":"一排子弹呼啸而出。"}},{"en":"a lot of questions, comments, offensive remarks, etc. that are directed at somebody quickly one after the other","cn":"（质问、评论、辱骂等的）接连发出","ex":{"en":"She faced a volley of angry questions from her mother.","cn":"她受到母亲一连串愤怒的质问。"}},{"en":"to hit or kick the ball before it touches the ground","cn":"拦截（空中球）；截击；凌空抽射","ex":{"en":"He volleyed the ball into the back of the net.","cn":"他凌空一脚把球踢入网窝。"},"pos":"verb"}]}},"vowel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"元音","en":"A vowel is a sound such as the ones represented in writing by the letters 'a', 'e' 'i', 'o' and 'u', which you pronounce with your mouth open, allowing the air to flow through it.","ex":{"en":"The vowel in words like 'my' and 'thigh' is not very difficult.","cn":"单词my和thigh中的元音并不难发。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the human speech sounds that you make by letting your breath flow out without closing any part of your mouth or throat","cn":"元音"},{"en":"a letter of the alphabet used to represent a vowel. In English the vowels are a, e, i, o, u, and sometimes y.","cn":"元音字母〔英语的元音字母为a、e、i、o、u﹐有时也包括y〕"}]},"collocations":{"phrases":["ADJ. long, short | open | neutral This neutral vowel is known as &lsquo;schwa&rsquo;. | weak | broad, flat | final | accented, stressed | un","VERB + VOWEL begin with, contain, end in/with","VOWEL + NOUN sound | system"]},"media":{"uk":"media/ldoce/hwd/bre/f/vowel0205.mp3","us":"media/ldoce/hwd/ame/9/vowel.mp3"},"examples":[{"en":"Each language has a different vowel system.","cn":"每种语言都有不同的元音系统。"},{"en":"vowel sounds","cn":"元音"}],"oxford":{"phon":"ˈvaʊəl","pos":"noun","senses":[{"en":"a speech sound in which the mouth is open and the tongue is not touching the top of the mouth, the teeth, etc., so that the flow of air is not limited, for example /ɑː, e, ɔː/","cn":"元音","lab":"phonetics","ex":{"en":"vowel sounds","cn":"元音"}},{"en":"a letter that represents a vowel sound. In English the vowels are a, e, i, o and u.","cn":"元音字母"}]}},"vogue":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"时尚;时髦;流行;风尚","en":"If there is a vogue for something, it is very popular and fashionable.","ex":{"en":"Despite the vogue for so-called health teas, there is no evidence that they are any healthier","cn":"尽管现在流行所谓的健康茶饮，但没有证据证明这些茶更有益健康。"}},{"pos":"PHRASE 短语","cn":"正在流行/变得流行","en":"If something is in vogue, is very popular and fashionable. If it comes into vogue, it becomes very popular and fashionable.","ex":{"en":"Pale colours are much more in vogue than autumnal bronzes and coppers.","cn":"浅色比黄褐色和红棕色这些秋季色彩更流行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a style of clothes, hair, behaviour etc that is fashionable. Fashion is also used as an uncountable noun, when talking about all of these styles in general","cn":""},{"en":"if there is a vogue for something, or it is in vogue , it is fashionable. Vogue sounds more formal and typical of the language that more educated speakers use than fashion","cn":""},{"en":"a way of doing something or a way of thinking that is becoming fashionable or popular","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If something is the latest vogue , it is the latest fashion. When your new hairstyle catches on, it's in vogue — or if it becomes unpopular, it’s not."}]},"collocations":{"phrases":["ADJ. current | temporary","VERB + VOGUE enjoy Cycling enjoyed a vogue at the end of the nineteenth century. | come (back) into Scooters have recently come back into vo","VOGUE + NOUN word","PREP. in ~ the type of pop song in vogue at that time | out of ~ Disaster movies are currently out of vogue. | ~ for the current vogue for J"]},"media":{"uk":"media/ldoce/hwd/bre/4/vogue0205.mp3","us":"media/ldoce/hwd/ame/b/vogue1.mp3"},"examples":[{"en":"Black is in vogue again.","cn":"黑色又成了流行色。"},{"en":"the vogue for child-centred education","cn":"以孩子为中心的教育潮流"}],"oxford":{"phon":"vəʊɡ","pos":"noun","senses":[{"en":"a fashion for something","cn":"流行；时髦；风行；风尚","lab":"North American English also","ex":{"en":"the vogue for child-centred education","cn":"以孩子为中心的教育潮流"}},{"en":"a magazine aimed at women published every month in many countries including Britain and the US, which contains articles about fashion, beauty, the arts and other subjects. It has a lot of influence in the fashion world. It first appeared in the US in 1892 and in Britain in 1916.","cn":"《时尚》杂志（面向女性的杂志，每月在包括英国和美国在内的许多国家出版，其中包含有关时尚、美容、艺术和其他主题的文章。它在时尚界有很大的影响力。它最早于 1892 年在美国出现，在 1916 年在英国出现。）","pos":""}]}},"vocative":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"呼格（词）","en":"A vocative is a word such as 'darling' or 'madam' which is used to address someone or attract their attention."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word or particular form of a word used to show that you are speaking or writing directly to someone","cn":"呼格词﹔呼格"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vocative.mp3","us":"media/ldoce/hwd/ame/6/vocative.mp3"},"examples":[{"en":"the vocative case","cn":"呼格"}],"oxford":{"phon":"ˈvɒkətɪv","pos":"adjective","senses":[{"en":"using or connected with the form of a noun, pronoun or an adjective used for talking to a person or thing","cn":"呼格；呼格词；呼语","ex":{"en":"the vocative case","cn":"呼格"}},{"en":"the form of a noun, a pronoun or an adjective used when talking to a person or thing","cn":"呼格；呼格词；呼语","pos":"noun"}]}},"voiced":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（发）浊音的","en":"A voiced speech sound is one that is produced with vibration of the vocal cords."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a voice that is deep, very high etc","cn":"嗓音深沉/尖细/沙哑的等"},{"en":"voiced sounds are made using the vocal cords . For example, /d/ and /g/ are voiced consonant s . 〔","cn":"音〕浊的〔如/d/和/ɡ/为浊辅音〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/voiced0205.mp3","us":"media/ldoce/hwd/ame/d/laadvoiced.mp3"},"oxford":{"phon":"vɔɪst","pos":"adjective","senses":[{"en":"produced by moving your vocal cords. In English the consonants /b d ɡ dʒ v ð z ʒ m n ŋ l r j w/ are voiced.","cn":"浊音性的；带声的"}]},"base":"voice"},"vouch":{"collins":{"senses":[{"pos":"","cn":"","en":"相关词组：vouch for"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you firmly believe that something is true or good because of your experience or knowledge of it","cn":"为…作担保﹐保证"},{"en":"to say that you believe that someone will behave well and that you will be responsible for their behaviour, actions etc","cn":"为〔某人的行为等〕作担保[保证]"}]},"vocab":{"pos":"v","senses":[{"en":"If you vouch for someone, you provide evidence or guarantee something on their behalf. If you vouch for your brother, you're saying he's a stand-up type of guy."}]},"media":{"uk":"media/ldoce/hwd/bre/f/vouch0205.mp3","us":"media/ldoce/hwd/ame/c/vouch.mp3"},"examples":[{"en":"I was in bed with the flu. My wife can vouch for that.","cn":"我患流感卧床休息了。我的妻子可为此作证。"},{"en":"I can vouch for her ability to work hard.","cn":"我保证她能够努力工作。"}]},"voluminous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"庞大的;浩繁的;大部头的","en":"Something that is voluminous is very large or contains a lot of things.","ex":{"en":"...a voluminous trench coat","cn":"宽大的军用雨衣"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a voluminous piece of clothing is very large and loose – often used humorously 〔","cn":"衣服〕宽大的﹐宽松的〔常为幽默用法〕"},{"en":"voluminous books, documents etc are very long and contain a lot of detail 〔","cn":"书籍﹑文件等〕篇幅长的﹐大部头的"},{"en":"a voluminous container is very large and can hold a lot of things 〔","cn":"容器〕大的﹐容量大的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Consider that volume is a measure of size. That will help you understand that voluminous refers to something very large in size or extent."}]},"media":{"uk":"media/ldoce/hwd/bre/5/voluminous0205.mp3","us":"media/ldoce/hwd/ame/c/voluminous.mp3"},"examples":[{"en":"I sank down into a voluminous armchair.","cn":"我一下子坐在了宽大的扶手椅里。"},{"en":"a voluminous skirt","cn":"肥大的裙子"}],"oxford":{"phon":"vəˈluːmɪnəs","pos":"adjective","senses":[{"en":"very large; having a lot of cloth","cn":"肥大的；宽松的；用布料多的","ex":{"en":"a voluminous skirt","cn":"肥大的裙子"}},{"en":"very long and detailed","cn":"浩繁的；大部头的；长篇的；冗长的","ex":{"en":"There is voluminous literature on modernism and post-modernism.","cn":"关于现代主义和后现代主义的文献有大量。"}},{"en":"very large","cn":"很大的","ex":{"en":"I sank down into a voluminous armchair.","cn":"我一下子坐在了宽大的扶手椅里。"}}]}},"vortex":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（风或水流形成的）漩涡，涡流","en":"A vortex is a mass of wind or water that spins round so fast that it pulls objects down into its empty centre.","ex":{"en":"The polar vortex is a system of wintertime winds.","cn":"极地涡旋是冬季风形成的一个风系。"}},{"pos":"N-COUNT 可数名词","cn":"（局势的）漩涡;无法控制的处境","en":"If you refer to a situation as a vortex, you feel that you are being forced into it without being able to prevent it.","ex":{"en":"When marriages break down children are swept into the vortex of their parents' embittered emotions.","cn":"当婚姻破裂时，孩子们也被卷进父母感情日益恶化的漩涡中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mass of wind or water that spins quickly and pulls things into its centre","cn":"旋风﹔漩涡"},{"en":"a situation that has a powerful effect on people’s lives and that influences their behaviour, even if they do not want it to 〔","cn":"感情或局势的〕漩涡"}]},"vocab":{"pos":"n","senses":[{"en":"Think vortex and picture a tornado or whirlpool — swirling around, causing destruction."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41vortex.mp3","us":"media/ldoce/hwd/ame/c/vortex.mp3"},"examples":[{"en":"They were caught up in a whirling vortex of emotion.","cn":"他们陷入了感情漩涡。"},{"en":"the vortex of emotions surrounding the case","cn":"围绕这宗案件的感情漩涡"}],"oxford":{"phon":"ˈvɔːteks","pos":"noun","senses":[{"en":"a mass of air, water, etc. that turns round and round very fast and pulls things into its centre","cn":"低涡；涡旋；旋涡","lab":"specialist"},{"en":"a very powerful feeling or situation that you cannot avoid or escape from","cn":"感情（或局势）的旋涡","lab":"literary","ex":{"en":"They were caught up in a whirling vortex of emotion.","cn":"他们陷入了感情旋涡。"}}]}},"voucher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"代金券;票券","en":"A voucher is a ticket or piece of paper that can be used instead of money to pay for something.","ex":{"en":"The winners will each receive a voucher for a pair of cinema tickets.","cn":"获胜者每人将会获得两张电影票的代金券。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ticket that can be used instead of money for a particular purpose","cn":"代金券"},{"en":"an official statement or receipt that is given to someone to prove that their accounts are correct or that money has been paid","cn":"收据﹐凭单"}]},"vocab":{"pos":"n","senses":[{"en":"A voucher is a certificate or document that either allows you to purchase something or proves that you paid for something. A voucher is sometimes valuable."}]},"collocations":{"phrases":["ADJ. credit | discount, money-off | gift, sales, shopping | luncheon | travel | accommodation, hotel | fuel, petrol","VERB + VOUCHER give sb, issue (sb with) The company issues travel vouchers to all managers. | get, receive I got a credit voucher for &pound","VOUCHER + VERB entitle sb to sth a voucher entitling you to a half-price meal | be worth sth a voucher worth &pound; 100 | be redeemable a 5","PREP. ~ for a voucher for children's glasses"]},"media":{"uk":"media/ldoce/hwd/bre/c/voucher0205.mp3","us":"media/ldoce/hwd/ame/1/voucher.mp3"},"examples":[{"en":"This discount voucher entitles you to 10% off your next purchase.","cn":"凭这张优惠券你下次购物可打九折。"},{"en":"a voucher for a free meal","cn":"免费用餐券"}],"oxford":{"phon":"ˈvaʊtʃə(r)","pos":"noun","senses":[{"en":"a printed piece of paper or an electronic code that can be used instead of money to pay for something, or that allows you to pay less than the usual price of something","cn":"代金券，票券","ex":{"en":"a voucher for a free meal","cn":"免费用餐券"}}]}},"voyeur":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"窥淫癖者","en":"A voyeur is someone who gets sexual pleasure from secretly watching other people having sex or taking their clothes off."},{"pos":"N-COUNT 可数名词","cn":"好刺探他人隐私者","en":"If you describe someone as a voyeur, you disapprove of them because you think they enjoy watching other people's suffering or problems.","ex":{"en":"The media has made unfeeling voyeurs of all of us.","cn":"媒体把我们所有人都变成了无情刺探他人隐私的人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gets sexual pleasure from secretly watching other people’s sexual activities","cn":"窥淫狂者﹐窥淫癖者"},{"en":"someone who enjoys watching other people’s private behaviour or suffering","cn":"喜欢窥探别人隐私的人"}]},"vocab":{"pos":"n","senses":[{"en":"Make sure you close the curtains at night, just in case there’s a voyeur in the neighborhood. A voyeur is someone who likes to watch people without them knowing."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld44voyeur.mp3","us":"media/ldoce/hwd/ame/e/voyeur.mp3"},"examples":[{"en":"a voyeuristic interest in other people's lives","cn":"对他人生活怀有窥秘癖的兴趣"}],"oxford":{"phon":"vɔɪˈɜː(r)","pos":"noun","senses":[{"en":"a person who gets pleasure from secretly watching people who are wearing no clothes or having sex","cn":"窥阴癖者（喜欢偷窥他人裸体或性交）"},{"en":"a person who enjoys watching the problems and private lives of others","cn":"刺探隐秘者（喜欢刺探他人的问题或私生活）","ex":{"en":"Most writers are voyeurs of a kind.","cn":"大部份作家都有点像窥秘者。"}}]}},"volte-face":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（观点或决定的）大转变，彻底转变，180度大转弯","en":"If you say that someone's behaviour is a volte-face, you mean that they have changed their opinion or decision completely, so that it is the opposite of what it was before.","ex":{"en":"The day's events were a remarkable volte-face.","cn":"当日发生的事件是一次惊人的大转折。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a change to a completely opposite opinion or plan of action 〔","cn":"意见﹑行动计划等的〕完全改变﹐大转变﹐180度大转弯"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41volte-face.mp3","us":"media/ldoce/hwd/ame/f/ld41volte-face.mp3"},"examples":[{"en":"This represents a volte-face in government thinking.","cn":"这代表着政府观点的彻底转变。"}],"oxford":{"phon":"ˌvɒlt ˈfɑːs","pos":"noun","senses":[{"en":"a complete change of opinion or plan","cn":"（意见或计划的）大转变，完全转变","ex":{"en":"This represents a volte-face in government thinking.","cn":"这代表着政府观点的彻底转变。"}}]}},"vociferous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表达观点时）大声的,激昂的","en":"If you describe someone as vociferous, you mean that they speak with great energy and determination, because they want their views to be heard.","ex":{"en":"He was a vociferous opponent of Conservatism","cn":"他高声反对保守主义。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"expressing your opinions loudly and strongly 〔","cn":"表述自己观点时〕大声的﹐激昂的"}]},"vocab":{"pos":"adj","senses":[{"en":"Vociferous describes loudmouths, such as the vociferous mob at the soccer game."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vociferous0205.mp3","us":"media/ldoce/hwd/ame/b/vociferous.mp3"},"examples":[{"en":"a vociferous critic of the president's stance","cn":"猛烈批评总统所持态度的人"},{"en":"vociferous protests","cn":"高声的抗议"}],"oxford":{"phon":"vəˈsɪfərəs","pos":"adjective","senses":[{"en":"expressing your opinions or feelings in a loud and confident way","cn":"大声疾呼的；喧嚣的；大叫大嚷的","ex":{"en":"vociferous protests","cn":"高声的抗议"}}]}},"voluble":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"健谈的;滔滔不绝的","en":"If you say that someone is voluble, you mean that they talk a lot with great energy and enthusiasm.","ex":{"en":"She was voluble with excitement","cn":"她由于激动变得很健谈。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"talking a lot or talking quickly 〔","cn":"讲话〕滔滔不绝的﹐流利的"}]},"vocab":{"pos":"adj","senses":[{"en":"Voluble describes someone who talks a lot, like your aunt who can’t stop telling you to cut your hair or a political candidate who makes twenty speeches on the day before the election."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41voluble.mp3","us":"media/ldoce/hwd/ame/0/voluble.mp3"},"examples":[{"en":"Evelyn was very voluble on the subject of women's rights.","cn":"伊夫林谈起女权这个话题口若悬河。"},{"en":"voluble protests","cn":"振振有词的抗议"}],"oxford":{"phon":"ˈvɒljəbl","pos":"adjective","senses":[{"en":"talking a lot, and with enthusiasm, about a subject","cn":"健谈的；滔滔不绝的","ex":{"en":"Evelyn was very voluble on the subject of women's rights.","cn":"伊夫林谈起女权这个话题口若悬河。"}},{"en":"expressed in many words and spoken quickly","cn":"流利的；明快的","ex":{"en":"voluble protests","cn":"振振有词的抗议"}}]}},"vole":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"田鼠","en":"A vole is a small animal that looks like a mouse but has very small ears and a short tail. Voles usually live in fields or near rivers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small animal like a mouse with a short tail that lives in fields and woods and near rivers","cn":"田鼠"}]},"media":{"uk":"media/ldoce/hwd/bre/3/vole0205.mp3","us":"media/ldoce/hwd/ame/5/vole.mp3"},"oxford":{"phon":"vəʊl","pos":"noun","senses":[{"en":"a small animal like a mouse or rat that lives in fields or near rivers","cn":"田鼠"}]}},"vocab":{"lemma":"vocabulary","media":{"uk":"media/ldoce/hwd/bre/5/ld41vocab.mp3","us":"media/ldoce/hwd/ame/c/vocab.mp3"}}});
